## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/blepharoplastyLogic.ts`

```typescript
// Blepharoplasty / Ptosis Repair Clinical Decision Logic
// Based on: AAO-HNS Clinical Practice Guidelines; CMS LCD L34462
// Also: ASOPRS Guidelines; Ophthalmology Society functional criteria

export interface BlepharoplastyInput {
  age: number;
  sex: 'male' | 'female';

  // Procedure type
  procedureType: 'upper-blepharoplasty' | 'lower-blepharoplasty' | 'ptosis-repair' | 'combined';

  // Visual field impairment (functional criteria)
  visualFieldDefect: boolean;
  superiorVisualFieldLoss: number; // degrees of superior visual field loss (0-90)
  marginalReflexDistance: number; // MRD1 in mm (ptosis: MRD1 ≤2mm)
  levatorFunction: number; // mm of levator excursion (poor: <4mm, fair: 4-7mm, good: >7mm)

  // Functional symptoms
  visualObstruction: boolean; // skin/fat obstructing vision
  ptosisPresent: boolean;
  ptosisUnilateral: boolean;
  dermatochalasis: boolean; // excess eyelid skin
  fatProlapse: boolean; // fat herniation
  browPtosis: boolean; // brow ptosis contributing to visual obstruction
  ectropion: boolean; // lower lid ectropion
  entropion: boolean; // lower lid entropion
  lagophthalmos: boolean; // incomplete eye closure

  // Functional impact
  difficultyReading: boolean;
  difficultyDriving: boolean;
  difficultyWithActivities: boolean;
  headacheFromBrowCompensation: boolean; // frontalis overuse headaches
  eyeStrain: boolean;
  symptomDurationMonths: number;

  // Objective measurements
  marginalReflexToLidFold: number; // MRD to lid fold distance (mm)
  excessSkinOverhang: boolean; // skin touching or overhanging lashes

  // Conservative treatment
  triedEyelidTaping: boolean;
  triedPtosisProps: boolean; // for ptosis

  // Surgical risk
  asa: 1 | 2 | 3 | 4;
  dryEye: boolean;
  thyroidEyeDisease: boolean;
  priorEyelidSurgery: boolean;
  anticoagulation: boolean;
}

export interface BlepharoplastyResult {
  candidacyScore: number;
  recommendation: 'Strongly Indicated (Functional)' | 'Indicated (Functional)' | 'Cosmetic Only' | 'Not Indicated';
  functionalCriteriaMet: boolean;
  ptosisGrade: string;
  keyFindings: string[];
  warnings: string[];
  coverageExpectation: string;
  references: string[];
}

export function calculateBlepharoplastyScore(input: BlepharoplastyInput): BlepharoplastyResult {
  const warnings: string[] = [];
  const keyFindings: string[] = [];
  let score = 0;
  let functionalCriteriaMet = false;

  // Ptosis grade
  let ptosisGrade = 'N/A';
  if (input.ptosisPresent) {
    if (input.marginalReflexDistance <= 1) {
      ptosisGrade = 'Severe ptosis (MRD1 ≤1mm)';
      score += 40;
      functionalCriteriaMet = true;
      keyFindings.push(`Severe ptosis: MRD1 ${input.marginalReflexDistance}mm — functional criteria met; CMS LCD L34462 criterion satisfied`);
    } else if (input.marginalReflexDistance <= 2) {
      ptosisGrade = 'Moderate ptosis (MRD1 ≤2mm)';
      score += 30;
      functionalCriteriaMet = true;
      keyFindings.push(`Moderate ptosis: MRD1 ${input.marginalReflexDistance}mm — functional criteria met`);
    } else if (input.marginalReflexDistance <= 3) {
      ptosisGrade = 'Mild ptosis (MRD1 3mm)';
      score += 15;
      keyFindings.push(`Mild ptosis: MRD1 ${input.marginalReflexDistance}mm — functional criteria borderline; visual field testing recommended`);
    } else {
      ptosisGrade = 'Normal (MRD1 >3mm)';
      keyFindings.push(`MRD1 ${input.marginalReflexDistance}mm — within normal range; visual field testing required to establish functional indication`);
    }
  }

  // Visual field loss — primary functional criterion
  if (input.visualFieldDefect && input.superiorVisualFieldLoss >= 12) {
    score += 35;
    functionalCriteriaMet = true;
    keyFindings.push(`Superior visual field loss ${input.superiorVisualFieldLoss}° — meets CMS criterion of ≥12° superior visual field defect`);
  } else if (input.visualFieldDefect && input.superiorVisualFieldLoss >= 8) {
    score += 20;
    keyFindings.push(`Superior visual field loss ${input.superiorVisualFieldLoss}° — borderline; most payers require ≥12° for coverage`);
  } else if (input.visualFieldDefect) {
    score += 10;
    keyFindings.push(`Visual field defect present — quantify with Humphrey or Goldmann perimetry`);
  }

  // Dermatochalasis with visual obstruction
  if (input.dermatochalasis && input.visualObstruction) {
    score += 25;
    functionalCriteriaMet = true;
    keyFindings.push('Dermatochalasis with visual obstruction — functional upper blepharoplasty indicated');
  } else if (input.dermatochalasis && input.excessSkinOverhang) {
    score += 15;
    keyFindings.push('Dermatochalasis with skin touching/overhanging lashes — document visual field testing');
  }

  // Functional symptoms
  if (input.difficultyReading) { score += 10; keyFindings.push('Difficulty reading due to visual obstruction'); }
  if (input.difficultyDriving) { score += 10; keyFindings.push('Difficulty driving due to visual obstruction'); }
  if (input.headacheFromBrowCompensation) { score += 8; keyFindings.push('Frontalis overuse headaches from brow compensation for ptosis'); }
  if (input.eyeStrain) { score += 5; keyFindings.push('Eye strain from compensatory brow elevation'); }
  if (input.difficultyWithActivities) { score += 8; keyFindings.push('Limitation of daily activities due to visual obstruction'); }

  // Duration
  if (input.symptomDurationMonths >= 12) {
    score += 5;
    keyFindings.push(`${input.symptomDurationMonths} months of functional symptoms`);
  }

  // Lower blepharoplasty / ectropion / entropion
  if (input.ectropion) {
    score += 30;
    functionalCriteriaMet = true;
    keyFindings.push('Ectropion — functional lower blepharoplasty/repair indicated; risk of corneal exposure');
    warnings.push('Ectropion — corneal exposure risk; ophthalmology consultation recommended');
  }
  if (input.entropion) {
    score += 30;
    functionalCriteriaMet = true;
    keyFindings.push('Entropion — functional repair indicated; risk of corneal abrasion from lash trichiasis');
  }
  if (input.lagophthalmos) {
    score += 25;
    functionalCriteriaMet = true;
    keyFindings.push('Lagophthalmos — incomplete eye closure; functional repair indicated to prevent corneal exposure keratopathy');
    warnings.push('Lagophthalmos — corneal exposure risk; lubrication and protective eyewear required pending repair');
  }

  // Risk factors
  if (input.dryEye) {
    warnings.push('Dry eye syndrome — increased risk of post-operative dry eye worsening; Schirmer test and ophthalmology evaluation recommended pre-operatively');
  }
  if (input.thyroidEyeDisease) {
    warnings.push('Thyroid eye disease — surgery contraindicated during active disease phase; thyroid function and ophthalmology clearance required; wait ≥6 months after disease stabilization');
    score -= 15;
  }
  if (input.anticoagulation) {
    warnings.push('Anticoagulation — increased bleeding risk; coordinate with prescribing physician for peri-operative management');
  }
  if (input.asa >= 4) {
    warnings.push('ASA Class IV — very high surgical risk; risk-benefit discussion required');
    score -= 15;
  }

  score = Math.max(0, Math.min(100, score));

  let recommendation: BlepharoplastyResult['recommendation'];
  let coverageExpectation: string;

  if (functionalCriteriaMet && score >= 40) {
    recommendation = 'Strongly Indicated (Functional)';
    coverageExpectation = 'Likely covered by Medicare and most commercial payers — functional criteria met. Document visual field testing, MRD measurements, and functional symptoms in prior authorization request.';
  } else if (functionalCriteriaMet || score >= 25) {
    recommendation = 'Indicated (Functional)';
    coverageExpectation = 'Coverage possible — borderline functional criteria. Obtain visual field testing with and without eyelid tape to document functional improvement. Document all functional symptoms thoroughly.';
  } else if (score >= 10) {
    recommendation = 'Cosmetic Only';
    coverageExpectation = 'Likely cosmetic — functional criteria not met. Insurance coverage unlikely without visual field testing demonstrating ≥12° superior field defect or MRD1 ≤2mm for ptosis.';
  } else {
    recommendation = 'Not Indicated';
    coverageExpectation = 'Not indicated at this time — insufficient functional criteria. Reassess if symptoms progress.';
  }

  return {
    candidacyScore: score,
    recommendation,
    functionalCriteriaMet,
    ptosisGrade,
    keyFindings,
    warnings,
    coverageExpectation,
    references: [
      'CMS LCD L34462. Blepharoplasty. Centers for Medicare & Medicaid Services — Coverage criteria: ≥12° superior visual field defect, MRD1 ≤2mm for ptosis, or functional impairment documented by visual field testing',
      'American Academy of Ophthalmology. Preferred Practice Pattern: Ptosis. 2018 — Classification and management of ptosis; MRD1 ≤2mm indicates functional ptosis requiring repair',
      'Cahill KV, Bradley EA, Meyer DR, et al. Functional Indications for Upper Eyelid Ptosis and Blepharoplasty Surgery. Ophthalmology. 2011;118(12):2510-2517. PMID: 21906817 — Evidence base for functional criteria in upper eyelid surgery',
      'Jacobs SW. Regarding the Schnur Scale and Blepharoplasty. Plast Reconstr Surg. 2002 — Visual field testing methodology for establishing functional blepharoplasty indication',
      'American Society of Ophthalmic Plastic and Reconstructive Surgery (ASOPRS). Position Statement on Functional Blepharoplasty. 2019 — Functional criteria and documentation requirements for insurance coverage',
    ],
  };
}
